\label{opeSPJMDPKM}
Let $s\in(0,1)$. Let $A:\mathbb{R}^N\to\mathbb{R}^{N\times N}$ be bounded and measurable. Assume that~$A$ is uniformly elliptic, namely that there exist constants $0<\lambda_A\leqslant\Lambda_A<+\infty$ such that, for every~$x, \xi\in\mathbb{R}^N$,
\[
\lambda_A |\xi|^2\leqslant A(x)\xi\cdot\xi\leqslant\Lambda_A |\xi|^2.
\]
Can one find a nonnegative kernel $k_A$ such that
\begin{equation}\label{lòkgyftdresdetfyguhijok}
k_A(x,y)=k_A(y,x),
\end{equation}
and, for some $\alpha\in(0,2)$, $\eta>0$, $0<\lambda\leqslant\Lambda<+\infty$, and~$M>0$,
\begin{alignat}{2}\label{srdtfyguioplèòlkoijhugyftr1}
&\lambda\leqslant k_A(x,y)|x-y|^{N+\alpha}\leqslant\Lambda,\quad&&\mbox{ for } |x-y|\leqslant 1,\\ \label{srdtfyguioplèòlkoijhugyftr2}
\mbox{ and }\quad &k_A(x,y)\leqslant M|x-y|^{-N-\eta},\quad&&\mbox{ for } |x-y|>1,
\end{alignat}
such that
\begin{equation}\label{mnbhgvcfdxszxdfcgvhb}
\int_{\mathbb{R}^N} A(x)D^s u(x)\cdot D^s v(x)\,dx = \iint_{\mathbb{R}^{2N}}(u(x)-u(y))(v(x)-v(y))k_A(x,y)\,dx\,dy
\end{equation}
for every~$u,v\in C_c^{\infty}(\mathbb{R}^N)$?

\label{propsuppcompatto}
Let $s\in(0,1)$ and $A:\mathbb{R}^N\to\mathbb{R}^{N\times N}$ be a bounded and uniformly elliptic matrix. Suppose that there exists a kernel
\[
k_A\in L^1_{\mathrm{loc}}(\mathbb{R}^{2N}\setminus\Delta)
\]
such that, for some $\alpha\in(0,2)$, $\eta>0$, and $\Lambda,M>0$,
\begin{alignat}{2}
k_A(x,y)&\leqslant \Lambda |x-y|^{-N-\alpha}&&\quad\mbox{ for } |x-y|\leqslant 1, \label{poiuytresdxcvghbnjm}\\
k_A(x,y)&\leqslant M |x-y|^{-N-\eta}&&\quad\mbox{ for } |x-y|>1. \label{cxzsedrftyhujiko098765r4e3wq2a<}
\end{alignat}
Moreover, assume that \eqref{mnbhgvcfdxszxdfcgvhb} holds for every~$u\in C_c^{\infty}(\mathbb{R}^N)$.

Then, for every~$R_0>0$ there exist~$(x,y)\in\mathbb{R}^{2N}$ with $|x-y|>R_0$
such that~$k_A(x,y)\ne0$.

\label{BAsymbol}
Let $A\in\mathbb{R}^{N\times N}$ be a constant matrix and let $\mathcal{B}_A$ defined as in~\eqref{BAdef1}. 

Then,
\begin{equation}\label{BAfourier}
 \mathcal{B}_A(u,v)=\int_{\mathbb{R}^N}p_A(\xi)\widehat{u}(\xi)\overline{\widehat{v}(\xi)}\,d\xi,
\end{equation}
where, for any $\xi\in\mathbb{R}^N$, 
\begin{equation}\label{ncewuri4y3itiyuwhdwuiefdefu5i654}
 p_A(\xi):=|\xi|^{2s-2}\,\xi\cdot A\xi.
\end{equation}

\label{prop:E1normalization}
Let $s\in(0,1)$. Then, for every~$u,v\in\mathcal S(\mathbb R^N)$,
\begin{equation}\label{E1normalization}
\mathcal{E}_1(u,v)=\int_{\mathbb{R}^N}D^su(x)\cdot D^sv(x) dx.
\end{equation}

\label{lemmafindiff}
For $u\in\mathcal S(\mathbb{R}^N)$ and~$h\in\mathbb{R}^N$, 
\begin{equation*}
\int_{\mathbb{R}^N}(u(x)-u(x-h))(v(x)-v(x-h))\,dx = 2\int_{\mathbb{R}^N}\left(1-\cos(h\cdot\xi)\right)\widehat{u}(\xi)\overline{\widehat{v}(\xi)}\,d\xi.
\end{equation*}

\label{lemmint}
Let $s\in (0, 1)$. Then, 
\begin{equation}\label{kappasconstant}
\kappa_s:=\int_0^{+\infty}\frac{1-\cos r}{r^{1+2s}}\,dr
\end{equation}
is finite and positive. 

Moreover, for any $t\in\mathbb{R}$, 
\begin{equation}\label{radscaling}
 \int_0^{+\infty}\frac{1-\cos(rt)}{r^{1+2s}}\,dr
 =\kappa_s|t|^{2s}.
\end{equation}

\label{propEmsymbol}
For $u,v\in\mathcal S(\mathbb{R}^N)$, we have that
\[
\mathcal{E}_m(u,v)=\int_{\mathbb{R}^N}\psi_m(\xi)\,\widehat{u}(\xi)\,\overline{\widehat{v}(\xi)}\, d\xi,
\]
where
\begin{equation}\label{lòkjhgfdtresdtfyguhijokpl}
\psi_m(\xi):=
\begin{cases}\displaystyle
c_{N,s}\kappa_s|\xi|^{2s}\int_{\mathbb S^{N-1}}m(\theta)\left|\frac{\xi}{|\xi|}\cdot\theta\right|^{2s}\,d\theta &{\mbox{ if~$\xi\neq 0$,}}\\
0 &{\mbox{ if~$\xi=0$,}}\end{cases}
\end{equation}
being $\kappa_s$ as in~\eqref{kappasconstant}.

\label{lemmauguale1}
For $\omega\in\mathbb S^{N-1}$, define
\begin{equation}\label{JNsdefn}
J_{N,s}(\omega):=\int_{\mathbb S^{N-1}}|\omega\cdot\theta|^{2s}\,d\theta.
\end{equation}
Then, $J_{N,s}(\omega)=J_{N,s}$ 
is independent of the direction~$\omega$
and it is strictly positive. 

Moreover,
\begin{equation}\label{xsrdcftvgbhnjkm,lkmjnbhgv}
 c_{N,s}\kappa_sJ_{N,s}=1,
\end{equation}
being $\kappa_s$ as in~\eqref{kappasconstant}.

\label{lemmaspherical}
Let $A\in\mathbb{R}^{N\times N}$ be symmetric and let $\omega\in\mathbb S^{N-1}$.  Then,
\begin{equation}\label{lsqkdJNCHUBSAKMOXxcsdjbhvhn}
 \frac{\displaystyle\int_{\mathbb S^{N-1}}(\theta\cdot A\theta)|\omega\cdot\theta|^{2s}\,d\theta}{\displaystyle\int_{\mathbb S^{N-1}}|\omega\cdot\theta|^{2s}\,d\theta}=\frac{\operatorname{tr}(A)+2s\,\omega\cdot A\omega}{N+2s}.
\end{equation}

\label{lemmatecnico2.2}
Let $\gamma>0$ and~$N\geqslant 1$. Assume that $K\in L^1_{loc}(\mathbb{R}^N\setminus\{0\})$ satisfies, for every~$r>0$,
\begin{equation}\label{ò.,adklms<cgvysjnzklm,}
K(r\zeta)=r^{-\gamma}K(\zeta)\quad\mbox{for a.e. }\zeta\ne0.
\end{equation}

Then, there exists $m\in L^1(\mathbb S^{N-1})$ such that
\[
K(\rho\theta)=\rho^{-\gamma}m(\theta)\quad\mbox{ for a.e.  }(\rho,\theta)\in(0,+\infty)\times\mathbb S^{N-1}.
\]
